package com.deutschai.app

private fun levelSentenceCourse(
    level: String,
    id: String,
    title: String,
    subtitle: String,
    vararg rows: String
): SentenceCourseDefinition = SentenceCourseDefinition(
    id = id,
    title = title,
    subtitle = subtitle,
    level = level,
    items = rows.map { row ->
        val fields = row.split("§", limit = 3)
        require(fields.size == 3) { "Invalid sentence-course row: $row" }
        SentencePracticeItem(fields[0], fields[1], fields[2])
    }
)

